#include "aurions/task_run_store.hpp"
#include <chrono>
#include <filesystem>
#include <iostream>
#include <stdexcept>
#include <sqlite3.h>
int main(){auto n=std::chrono::steady_clock::now().time_since_epoch().count();auto root=std::filesystem::temp_directory_path()/("aurions-taskrun-"+std::to_string(n));auto db=root/"nested"/"run.sqlite";bool pass=false;try{std::filesystem::create_directories(root);auto future_db=root/"future-schema.sqlite";sqlite3*future=nullptr;if(sqlite3_open(future_db.string().c_str(),&future)!=SQLITE_OK)throw std::runtime_error("create future schema fixture");if(sqlite3_exec(future,"PRAGMA user_version=99",nullptr,nullptr,nullptr)!=SQLITE_OK){sqlite3_close(future);throw std::runtime_error("set future schema fixture");}sqlite3_close(future);bool future_rejected=false;try{aurions::TaskRunStore unsupported(future_db);}catch(const std::exception&){future_rejected=true;}if(!future_rejected)throw std::runtime_error("future schema version accepted");{aurions::TaskRunStore versioned(root/"versioned.sqlite");sqlite3*checkdb=nullptr;if(sqlite3_open((root/"versioned.sqlite").string().c_str(),&checkdb)!=SQLITE_OK)throw std::runtime_error("read schema version fixture");sqlite3_stmt*version_stmt=nullptr;if(sqlite3_prepare_v2(checkdb,"PRAGMA user_version",-1,&version_stmt,nullptr)!=SQLITE_OK){sqlite3_close(checkdb);throw std::runtime_error("prepare schema version check");}if(sqlite3_step(version_stmt)!=SQLITE_ROW||sqlite3_column_int(version_stmt,0)!=1){sqlite3_finalize(version_stmt);sqlite3_close(checkdb);throw std::runtime_error("schema version not initialized");}sqlite3_finalize(version_stmt);sqlite3_close(checkdb);}std::string id;{aurions::TaskRunStore s(db);auto c=s.create("task:research",.4,R"({"max_steps":12})","cause:owner","actor:owner");id=c.id;if(c.state!="queued"||c.revision!=1)throw std::runtime_error("initial state");auto r=s.transition(id,1,"running","scheduler","cause:start","actor:runtime");if(r.revision!=2)throw std::runtime_error("start");bool noop=false;try{(void)s.transition(id,2,"running","control","cause:no-op","actor:owner");}catch(...){noop=true;}if(!noop)throw std::runtime_error("no-op accepted");auto p=s.transition(id,2,"paused","control","cause:pause","actor:owner","checkpoint:one");if(p.revision!=3||p.checkpoint_refs_json.find("checkpoint:one")==std::string::npos)throw std::runtime_error("checkpoint");auto rr=s.transition(id,3,"running","control","cause:resume","actor:owner");if(rr.revision!=4)throw std::runtime_error("resume");auto done=s.transition(id,4,"completed","postcondition","result:verified","actor:tester","checkpoint:final");if(done.revision!=5)throw std::runtime_error("complete");bool terminal_bad=false;try{(void)s.transition(id,5,"running","retry","cause:retry","actor:runtime");}catch(...){terminal_bad=true;}if(!terminal_bad)throw std::runtime_error("terminal accepted");bool stale=false;try{(void)s.transition(id,3,"paused","control","cause:stale","actor:owner");}catch(...){stale=true;}if(!stale)throw std::runtime_error("stale accepted");auto ev=s.transitions(id);if(ev.size()!=5||ev.front().previous_revision!=0||ev.back().revision!=5)throw std::runtime_error("events incomplete");auto lost=s.create("task:recovery",.1,"{}","cause:recover","actor:owner");auto l=s.transition(lost.id,1,"lost","heartbeat","cause:worker-missing","actor:runtime");if(l.revision!=2)throw std::runtime_error("lost transition");bool recon=false;try{(void)s.transition(lost.id,2,"running","recovery","cause:resume","actor:runtime");}catch(...){recon=true;}if(!recon)throw std::runtime_error("lost resumed without recon");auto recovered=s.transition(lost.id,2,"running","recovery","cause:reconciled","actor:runtime",std::nullopt,std::nullopt,"reconciliation:verified");if(recovered.revision!=3)throw std::runtime_error("recovery");}{aurions::TaskRunStore s(db);auto g=s.get(id);if(!g||g->state!="completed"||g->revision!=5)throw std::runtime_error("restart");if(s.transitions(id).size()!=5)throw std::runtime_error("transition count after restart");auto blocked=s.create("task:blocked",.2,"{}","cause:create","actor:owner");auto b=s.transition(blocked.id,1,"blocked","policy","cause:blocked","actor:runtime",std::nullopt,"failure:policy");if(!b.failure_ref||*b.failure_ref!="failure:policy")throw std::runtime_error("blocked failure reference");auto cancelled=s.transition(blocked.id,2,"cancelled","control","cause:cancel","actor:owner");if(cancelled.failure_ref)throw std::runtime_error("stale failure reference retained after cancellation");auto persisted=s.get(blocked.id);if(!persisted||persisted->failure_ref)throw std::runtime_error("failure reference persisted after cancellation");pass=true;}}catch(const std::exception&e){std::cerr<<"task-run test: "<<e.what()<<'\n';}std::error_code ec;std::filesystem::remove_all(root,ec);return pass&&!ec?0:1;}
